import React, { useState } from 'react';
import AuraCanvas from '../components/AuraCanvas';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_HUES = { 1:[0,20], 2:[15,350], 3:[40,30], 4:[155,175], 5:[200,220] };
const MOOD_LABEL = { 1:'Väldigt dåligt', 2:'Dåligt', 3:'Okej', 4:'Bra', 5:'Väldigt bra' };
const MOOD_EMOJI = { 1:'😔', 2:'😟', 3:'😐', 4:'🙂', 5:'😄' };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const [expanded, setExpanded]    = useState(null);
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);
  const avgRounded = Math.round(avgMood);

  if (isEmpty) return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      <AuraCanvas hues={[200,225]} intensity={0.45} speed={0.3} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center', padding:'0 32px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.3)', marginBottom:16 }}>Historik · Tom</p>
        <h2 style={{ fontSize:'clamp(28px,7vw,42px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:10 }}>Ingenting här än</h2>
        <p style={{ fontSize:14, color:'rgba(240,237,230,0.4)', marginBottom:36, fontWeight:300 }}>Börja med en tankeanalys.</p>
        <button onClick={()=>setPage('home')} style={{ padding:'13px 28px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0d0d0d', fontSize:13, fontWeight:600, border:'none' }}>
          Analysera en tanke
        </button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#0d0d0d', paddingBottom:100, position:'relative' }}>
      {/* Subtle ambient aura — fixed background */}
      <div style={{ position:'fixed', inset:0, zIndex:0 }}>
        <AuraCanvas hues={avgRounded>0?MOOD_HUES[avgRounded]:[200,220]} intensity={0.3} speed={0.2} />
      </div>

      <div style={{ position:'relative', zIndex:10, padding:'28px 22px 0' }}>

        {/* Header */}
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:32 }}>
          <div>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,237,230,0.3)', marginBottom:6 }}>Historik</p>
            <h1 style={{ fontSize:'clamp(28px,7vw,42px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', lineHeight:1.05 }}>
              {thoughts.length} {thoughts.length===1?'analys':'analyser'}
            </h1>
          </div>
          {streak > 0 && (
            <div style={{ background:'rgba(255,255,255,0.07)', border:'1px solid rgba(255,255,255,0.1)', borderRadius:100, padding:'8px 14px' }}>
              <span style={{ fontSize:12, color:'rgba(240,237,230,0.7)', fontWeight:500 }}>🔥 {streak} dagar</span>
            </div>
          )}
        </div>

        {/* Mood dots — unique visual, each day is a glowing orb */}
        {moods.length > 0 && (
          <div style={{ marginBottom:28 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,237,230,0.28)', marginBottom:14 }}>Senaste dagarna</p>
            <div style={{ display:'flex', gap:8, alignItems:'center', flexWrap:'wrap' }}>
              {[...moods].reverse().map((m, i) => {
                const hue = MOOD_HUES[m.score][0];
                const size = 32 + (m.score * 6);
                return (
                  <div key={i} title={MOOD_LABEL[m.score]} style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:4 }}>
                    <div style={{ width:size, height:size, borderRadius:'50%', background:`radial-gradient(circle at 35% 35%, hsla(${hue+20},65%,70%,0.9) 0%, hsla(${hue},55%,48%,0.8) 50%, hsla(${hue-10},50%,35%,0.6) 100%)`, boxShadow:`0 0 ${size/2}px hsla(${hue},60%,55%,0.3)`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:size*0.4 }}>
                      {MOOD_EMOJI[m.score]}
                    </div>
                    <span style={{ fontFamily:'DM Mono,monospace', fontSize:6.5, color:'rgba(240,237,230,0.25)' }}>
                      {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Divider */}
        <div style={{ height:1, background:'rgba(255,255,255,0.07)', marginBottom:24 }} />

        {/* Trap freq */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,237,230,0.28)', marginBottom:14 }}>Tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([label,count]) => (
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                <span style={{ fontSize:12, color:'rgba(240,237,230,0.5)', flex:1, fontWeight:300 }}>{label}</span>
                <div style={{ width:72, height:2, background:'rgba(255,255,255,0.07)', borderRadius:1 }}>
                  <div style={{ height:'100%', borderRadius:1, background:'rgba(240,237,230,0.3)', width:`${(count/maxTrap)*100}%` }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(240,237,230,0.25)', width:14, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={{ height:1, background:'rgba(255,255,255,0.07)', marginBottom:16 }} />
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,237,230,0.28)', marginBottom:12 }}>Tankelog</p>
            {thoughts.map((th, i) => (
              <div key={th.id} style={{ marginBottom:4 }}>
                <button onClick={() => setExpanded(expanded===i?null:i)}
                  style={{ width:'100%', textAlign:'left', padding:'14px 16px', background:expanded===i?'rgba(255,255,255,0.09)':'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.08)', borderRadius:expanded===i?'16px 16px 0 0':16, transition:'all .2s', display:'flex', alignItems:'center', gap:12, backdropFilter:'blur(12px)' }}>
                  <span style={{ fontSize:18 }}>{th.trap_icon||'◎'}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', marginBottom:4 }}>
                      <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,237,230,0.4)', textTransform:'uppercase', letterSpacing:'0.08em' }}>{th.trap_label}</span>
                      <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,237,230,0.22)' }}>{new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}</span>
                    </div>
                    <p style={{ fontSize:12, color:'rgba(240,237,230,0.35)', fontStyle:'italic', margin:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:expanded===i?'normal':'nowrap' }}>
                      "{th.user_text?.slice(0,80)}{th.user_text?.length>80&&expanded!==i?'...':''}"
                    </p>
                  </div>
                  <span style={{ fontSize:11, color:'rgba(240,237,230,0.2)', transform:expanded===i?'rotate(180deg)':'none', transition:'transform .25s', flexShrink:0 }}>↓</span>
                </button>
                {expanded===i && (
                  <div style={{ padding:'14px 16px', background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', borderTop:'none', borderRadius:'0 0 16px 16px', backdropFilter:'blur(12px)', animation:'fadeUp .25s both' }}>
                    <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(240,237,230,0.3)', marginBottom:8 }}>Omramning</p>
                    <p style={{ fontSize:13, color:'rgba(240,237,230,0.65)', lineHeight:1.78, fontWeight:300 }}>{th.reframe}</p>
                  </div>
                )}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
